ps -A -o USER,PID | while read user pid; do [ "$user" = shell ] || continue; args=$(tr '\000' ' ' < /proc/$pid/cmdline 2>/dev/null | sed 's/ *$//'); case "$args" in 'focusflow-bridge'|'app_process /system/bin ru.focusflow.pen.bridge.ProviderBridgeMain'|'app_process /system/bin --nice-name=focusflow-bridge ru.focusflow.pen.bridge.ProviderBridgeMain'|'app_process /system/bin ru.folio.notes.bridge.PenBridge') kill "$pid";; esac; done; if ! pidof folio-pen-shared >/dev/null; then sleep 0.4; jar=/data/local/tmp/folio-pen-shared-$$.apk; cp @APK@ "$jar" || exit 11; (CLASSPATH="$jar" setsid nohup app_process /system/bin --nice-name=folio-pen-shared ru.folio.penbridge.SharedPenBridge > /data/local/tmp/folio-pen-shared.log 2>&1 < /dev/null &); sleep 2; fi; if pidof folio-pen-shared >/dev/null; then echo FOLIO_FOCUSFLOW_STARTED; else cat /data/local/tmp/folio-pen-shared.log; exit 12; fi
